#!/usr/bin/env python3
import hashlib
import sys


def digest(data):
    return hashlib.sha256(data).hexdigest()


def fail(msg):
    print('FAIL: ' + msg)
    raise SystemExit(1)


class SnapshotError(Exception):
    pass


class Snapshot:
    def __init__(self, version, data):
        self.version = version
        self.data = dict(data)


class Store:
    def __init__(self):
        self.objects = {}
        self.manifests = {}
        self.root = None

    def publish(self, version, shards):
        if not shards:
            return False
        names = [item[0] for item in shards]
        if len(names) != len(set(names)):
            return False
        if version in self.manifests:
            return False
        records = []
        for name, data, expected in shards:
            if digest(data) != expected:
                return False
            records.append((name, len(data), expected))
            self.objects[(version, name)] = bytes(data)
        records.sort()
        body = version + '|' + '|'.join(
            name + ':' + str(length) + ':' + text
            for name, length, text in records
        )
        self.manifests[version] = {
            'records': tuple(records),
            'digest': digest(body.encode('utf-8')),
        }
        self.root = version
        return True

    def begin(self):
        return self.root

    def read_version(self, version):
        if version is None or version not in self.manifests:
            raise SnapshotError('missing manifest')
        manifest = self.manifests[version]
        body = version + '|' + '|'.join(
            name + ':' + str(length) + ':' + text
            for name, length, text in manifest['records']
        )
        if digest(body.encode('utf-8')) != manifest['digest']:
            raise SnapshotError('manifest digest')
        data = {}
        for name, expected_len, expected_hash in manifest['records']:
            payload = self.objects.get((version, name))
            if payload is None:
                raise SnapshotError('missing shard')
            if len(payload) != expected_len or digest(payload) != expected_hash:
                raise SnapshotError('shard digest')
            data[name] = payload
        return Snapshot(version, data)

    def open(self, version=None):
        selected = self.begin() if version is None else version
        return self.read_version(selected)


def test_manifest_and_snapshot():
    store = Store()
    one_a = b'v1-a'
    one_b = b'v1-b'
    ok = store.publish('v1', [
        ('a', one_a, digest(one_a)),
        ('b', one_b, digest(one_b)),
    ])
    if not ok:
        fail('v1 publication was rejected')
    fixed = store.begin()
    if fixed != 'v1':
        fail('root not v1 after publication')
    snap = store.read_version(fixed)
    if snap.version != 'v1' or snap.data['a'] != one_a or snap.data['b'] != one_b:
        fail('v1 snapshot content mismatch')

    two_a = b'v2-a'
    two_b = b'v2-b'
    ok = store.publish('v2', [
        ('a', two_a, digest(two_a)),
        ('b', two_b, digest(two_b)),
    ])
    if not ok:
        fail('v2 publication was rejected')
    old = store.read_version(fixed)
    if old.version != 'v1' or old.data['a'] != one_a or old.data['b'] != one_b:
        fail('fixed snapshot changed after v2 publication')

    manifest_v1 = store.manifests['v1']
    mixed = {}
    for index, item in enumerate(manifest_v1['records']):
        name = item[0]
        use_version = 'v1' if index == 0 else store.root
        mixed[name] = store.objects[(use_version, name)]
    if mixed['a'] == one_a and mixed['b'] == one_b:
        fail('negative control did not trigger: latest-following reader mixed')

